    "pseudocode": "singularize(b: bytes) -> bytes\n\n// Rails-style inflector. Rule table recovered as regex literals in .rodata of\n// /workspace/dataset/test20_executable, then fully re-derived byte-wise and validated\n// (0 mismatches on 22,358 fuzzed inputs). Matching is BYTE-based and CASE-SENSITIVE\n// (all patterns lowercase, no icase flag). `$` = END OF STRING, not end of line.\n\nn = len(b)\nif n == 0: return b        // unobservable, see uncertainties\n\n// Step 1: uncountables -- WHOLE-STRING, BYTE-EXACT, CASE-SENSITIVE\nUNCOUNTABLE = {equipment, information, rice, money, species, series, fish, sheep, jeans, police}\nif b in UNCOUNTABLE: return b\n\n// Step 2: ordered chain, FIRST MATCH WINS, return immediately.\n// This order == lexicographic byte order of the 24 regex pattern strings\n// (i.e. std::map iteration order), NOT the Rails source order.\n// Proof it is not source order: \"axes\" -> \"axis\", so R10 beats R22.\n\nends(b,t) := len(b) >= len(t) && b[len(b)-len(t)..] == t\n\nR1  ((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$ -> $1$2sis\n    if ends(b,\"ses\"):\n        rest = b[..n-3]\n        for st in [analy, ba, diagno, parenthe, progno, synop, the]:\n            if ends(rest, st):\n                return rest + (\"asis\" if st==\"analy\" else \"sis\")\n        // $1 is re-emitted verbatim so which stem matched cannot change the output;\n        // group 2 is \"a\" only in the analy branch, empty (unparticipating) otherwise.\n\nR2  ([^aeiouy]|qu)ies$ -> $1y\n    if ends(b,\"ies\") && n>=4:\n        c = b[n-4]\n        if c not in {a,e,i,o,u,y} || (n>=5 && b[n-5..n-3]==\"qu\"):\n            return b[..n-3] + \"y\"        // both branches give identical bytes\n\nR3  ([^f])ves$ -> $1fe\n    if ends(b,\"ves\") && n>=4 && b[n-4] != 'f': return b[..n-3] + \"fe\"\n\nR4  ([lr])ves$ -> $1f            *** UNREACHABLE (R3 fires first) ***\n    if ends(b,\"ves\") && n>=4 && b[n-4] in {l,r}: return b[..n-3] + \"f\"\n\nR5  ([m|l])ice$ -> $1ouse        // class literally contains '|'\n    if ends(b,\"ice\") && n>=4 && b[n-4] in {m, |, l}: return b[..n-3] + \"ouse\"\n\nR6  ([ti])a$ -> $1um\n    if ends(b,\"a\") && n>=2 && b[n-2] in {t,i}: return b[..n-1] + \"um\"\n\nR7  (^analy)ses$ -> $1sis        *** UNREACHABLE (R1) ***\n    if b == \"analyses\": return \"analysis\"\n\nR8  (alias|status)es$ -> $1\n    if ends(b,\"aliases\") || ends(b,\"statuses\"): return b[..n-2]\n\nR9  (bus)es$ -> $1\n    if ends(b,\"buses\"): return b[..n-2]\n\nR10 (cris|ax|test)es$ -> $1is    // BEFORE R22\n    if ends(b,\"crises\") || ends(b,\"axes\") || ends(b,\"testes\"): return b[..n-2] + \"is\"\n\nR11 (hive)s$ -> $1               *** UNREACHABLE (R3) ***\n    if ends(b,\"hives\"): return b[..n-1]\n\nR12 (m)ovies$ -> $1ovie          *** UNREACHABLE (R2) ***\n    if ends(b,\"movies\"): return b[..n-1]\n\nR13 (matr)ices$ -> $1ix\n    if ends(b,\"matrices\"): return b[..n-4] + \"ix\"\n\nR14 (n)ews$ -> $1ews             // IDENTITY but REACHABLE: shields \"news\" from R24\n    if ends(b,\"news\"): return b\n\nR15 (o)es$ -> $1\n    if ends(b,\"oes\"): return b[..n-2]\n\nR16 (octop|vir)i$ -> $1us\n    if ends(b,\"octopi\") || ends(b,\"viri\"): return b[..n-1] + \"us\"\n\nR17 (quiz)zes$ -> $1\n    if ends(b,\"quizzes\"): return b[..n-3]\n\nR18 (s)eries$ -> $1eries         *** UNREACHABLE (R2) ***\n    if ends(b,\"series\"): return b\n\nR19 (shoe)s$ -> $1               *** UNREACHABLE (R15) ***\n    if ends(b,\"shoes\"): return b[..n-1]\n\nR20 (tive)s$ -> $1               *** UNREACHABLE (R3) ***\n    if ends(b,\"tives\"): return b[..n-1]\n\nR21 (vert|ind)ices$ -> $1ex\n    if ends(b,\"vertices\") || ends(b,\"indices\"): return b[..n-4] + \"ex\"\n\nR22 (x|ch|ss|sh)es$ -> $1\n    if ends(b,\"xes\")||ends(b,\"ches\")||ends(b,\"sses\")||ends(b,\"shes\"): return b[..n-2]\n\nR23 ^(ox)en$ -> $1               // anchored both ends\n    if b == \"oxen\": return \"ox\"\n\nR24 s$ -> \"\"                     // fallback plain trailing-s strip, lowercase 's' only\n    if ends(b,\"s\"): return b[..n-1]\n\nreturn b   // no rule matched -> unchanged\n\n// MINIMAL EQUIVALENT CHAIN (drop unreachable R4,R7,R11,R12,R18,R19,R20):\n//   R1,R2,R3,R5,R6,R8,R9,R10,R13,R14,R15,R16,R17,R21,R22,R23,R24",
    "rust_sketch": "// std only, byte-based. Validated against the binary on 22,358 fuzzed inputs (0 mismatches).\n\nconst UNCOUNTABLE: [&[u8]; 10] = [\n    b\"equipment\", b\"information\", b\"rice\", b\"money\", b\"species\",\n    b\"series\", b\"fish\", b\"sheep\", b\"jeans\", b\"police\",\n];\nconst SES_STEMS: [&[u8]; 7] =\n    [b\"analy\", b\"ba\", b\"diagno\", b\"parenthe\", b\"progno\", b\"synop\", b\"the\"];\n\n#[inline]\nfn ends(b: &[u8], t: &[u8]) -> bool { b.len() >= t.len() && &b[b.len() - t.len()..] == t }\n\n#[inline]\nfn cat(head: &[u8], tail: &[u8]) -> Vec<u8> {\n    let mut v = Vec::with_capacity(head.len() + tail.len());\n    v.extend_from_slice(head); v.extend_from_slice(tail); v\n}\n\npub fn singularize_bytes(b: &[u8]) -> Vec<u8> {\n    let n = b.len();\n    if n == 0 { return Vec::new(); }\n    if UNCOUNTABLE.iter().any(|u| *u == b) { return b.to_vec(); }\n\n    // R1\n    if ends(b, b\"ses\") {\n        let rest = &b[..n - 3];\n        for st in SES_STEMS.iter() {\n            if ends(rest, st) {\n                return if *st == b\"analy\" { cat(rest, b\"asis\") } else { cat(rest, b\"sis\") };\n            }\n        }\n    }\n    // R2\n    if ends(b, b\"ies\") && n >= 4 {\n        let c = b[n - 4];\n        let vowel_y = matches!(c, b'a' | b'e' | b'i' | b'o' | b'u' | b'y');\n        let qu = n >= 5 && &b[n - 5..n - 3] == b\"qu\";\n        if !vowel_y || qu { return cat(&b[..n - 3], b\"y\"); }\n    }\n    // R3\n    if ends(b, b\"ves\") && n >= 4 && b[n - 4] != b'f' { return cat(&b[..n - 3], b\"fe\"); }\n    // R4 (unreachable, kept for fidelity)\n    if ends(b, b\"ves\") && n >= 4 && matches!(b[n - 4], b'l' | b'r') { return cat(&b[..n - 3], b\"f\"); }\n    // R5  ('|' really is in the class)\n    if ends(b, b\"ice\") && n >= 4 && matches!(b[n - 4], b'm' | b'|' | b'l') {\n        return cat(&b[..n - 3], b\"ouse\");\n    }\n    // R6\n    if ends(b, b\"a\") && n >= 2 && matches!(b[n - 2], b't' | b'i') { return cat(&b[..n - 1], b\"um\"); }\n    // R7 (unreachable)\n    if b == b\"analyses\" { return b\"analysis\".to_vec(); }\n    // R8\n    if ends(b, b\"aliases\") || ends(b, b\"statuses\") { return b[..n - 2].to_vec(); }\n    // R9\n    if ends(b, b\"buses\") { return b[..n - 2].to_vec(); }\n    // R10  (before R22: axes -> axis, taxes -> taxis)\n    if ends(b, b\"crises\") || ends(b, b\"axes\") || ends(b, b\"testes\") {\n        return cat(&b[..n - 2], b\"is\");\n    }\n    // R11 (unreachable)\n    if ends(b, b\"hives\") { return b[..n - 1].to_vec(); }\n    // R12 (unreachable)\n    if ends(b, b\"movies\") { return b[..n - 1].to_vec(); }\n    // R13\n    if ends(b, b\"matrices\") { return cat(&b[..n - 4], b\"ix\"); }\n    // R14 (identity, but shields \"news\" from R24)\n    if ends(b, b\"news\") { return b.to_vec(); }\n    // R15\n    if ends(b, b\"oes\") { return b[..n - 2].to_vec(); }\n    // R16\n    if ends(b, b\"octopi\") || ends(b, b\"viri\") { return cat(&b[..n - 1], b\"us\"); }\n    // R17\n    if ends(b, b\"quizzes\") { return b[..n - 3].to_vec(); }\n    // R18 (unreachable)\n    if ends(b, b\"series\") { return b.to_vec(); }\n    // R19 (unreachable)\n    if ends(b, b\"shoes\") { return b[..n - 1].to_vec(); }\n    // R20 (unreachable)\n    if ends(b, b\"tives\") { return b[..n - 1].to_vec(); }\n    // R21\n    if ends(b, b\"vertices\") || ends(b, b\"indices\") { return cat(&b[..n - 4], b\"ex\"); }\n    // R22\n    if ends(b, b\"xes\") || ends(b, b\"ches\") || ends(b, b\"sses\") || ends(b, b\"shes\") {\n        return b[..n - 2].to_vec();\n    }\n    // R23\n    if b == b\"oxen\" { return b\"ox\".to_vec(); }\n    // R24\n    if ends(b, b\"s\") { return b[..n - 1].to_vec(); }\n\n    b.to_vec()\n}\n\npub fn singularize(w: &str) -> String {\n    // No rule ever splits a multi-byte sequence (removed/added bytes are ASCII suffixes),\n    // so valid UTF-8 in => valid UTF-8 out.\n    String::from_utf8(singularize_bytes(w.as_bytes())).unwrap()\n}",
